param([string]$EnvFile='.\.env',[ValidateSet('Preview','Apply')][string]$Mode='Preview',[string]$Confirm='')
$ErrorActionPreference='Stop'
if($Mode-eq'Apply'-and$Confirm-cne'REDAKTION ALLE SEITEN BEREINIGEN'){throw 'Bestaetigung fehlt.'}
$v=@{};Get-Content $EnvFile|Where-Object{$_-match'^[^#].*='}|ForEach-Object{$p=$_-split'=',2;$v[$p[0].Trim()]=$p[1].Trim()}
foreach($n in @('GK_SITE_URL','GK_UNIFIED_API_TOKEN')){if([string]::IsNullOrWhiteSpace($v[$n])){throw "$n fehlt."}}
$site=$v.GK_SITE_URL.TrimEnd('/');$uh=@{Authorization='Bearer '+$v.GK_UNIFIED_API_TOKEN};$items=@()
foreach($kind in @('posts','pages')){$page=1;do{$url=$site+"/wp-json/wp/v2/$kind`?status=publish&per_page=100&page=$page&_fields=id,link,title,featured_media";try{$batch=@(Invoke-RestMethod $url -TimeoutSec 45);if($batch.Count-eq1-and$batch[0]-is[Array]){$batch=@($batch[0])}}catch{if($_.Exception.Response-and[int]$_.Exception.Response.StatusCode-eq400){$batch=@()}else{throw}};foreach($x in $batch){$x|Add-Member kind $kind -Force};$items+=$batch;$page++}while($batch.Count-eq100)}
$mediaCache=@{};function Media([long]$id){if($id-le0){return $null};if(-not$mediaCache.ContainsKey($id)){try{$mediaCache[$id]=Invoke-RestMethod ($site+"/wp-json/wp/v2/media/$id`?_fields=id,source_url,alt_text") -TimeoutSec 45}catch{$mediaCache[$id]=$null}};return $mediaCache[$id]}
$apl=Media 28086;$signal=Media 28085
function Match-One([string]$html,[string]$pattern){$m=[regex]::Match($html,$pattern);if($m.Success){return $m.Groups['body'].Value};return ''}
function Visual([string]$title,[long]$featured){$m=$null;if($title-match'(?i)APL'){$m=$apl}elseif($title-match'(?i)TAE|Endleitung|DSL.*Signal|Hausverkabelung'){$m=$signal}else{$m=Media $featured};if($null-eq$m-or[string]::IsNullOrWhiteSpace([string]$m.source_url)){return ''};$alt=[Net.WebUtility]::HtmlEncode($(if([string]::IsNullOrWhiteSpace([string]$m.alt_text)){"Schematische Darstellung zu $title"}else{[string]$m.alt_text}));return '<figure class="gk-article-visual"><img src="'+[string]$m.source_url+'" alt="'+$alt+'" loading="lazy"><figcaption>'+[Net.WebUtility]::HtmlEncode($title)+'</figcaption></figure>'}
function Clean-Core([string]$html){$x=$html;$x=[regex]::Replace($x,'(?is)<div\b[^>]*class=["''][^"'']*gk-article-intro[^"'']*["''][^>]*>.*?</div>','');$x=[regex]::Replace($x,'(?is)<figure\b[^>]*class=["''][^"'']*gk[_-]visual[^"'']*["''][^>]*>.*?</figure>','');$x=[regex]::Replace($x,'(?is)<div\b[^>]*class=["''][^"'']*gk-visual-placeholder[^"'']*["''][^>]*>.*?</div>','');$x=[regex]::Replace($x,'(?is)<p>\s*(?:Dieser Abschnitt erweitert den Beitrag|Kurz eingeordnet:|Dieser Beitrag ordnet).*?</p>','');$x=[regex]::Replace($x,'(?is)<h2\b[^>]*>\s*</h2>','');return $x.Trim()}
function Clean-Authority([string]$html){$x=[regex]::Replace($html,'(?is)^\s*<h2\b[^>]*>[^<]*ausf.hrliche Einordnung\s*</h2>\s*<p>Dieser Abschnitt erweitert den Beitrag.*?</p>','');return $x.Trim()}
function Strip-Noise([string]$html){$x=$html;$x=[regex]::Replace($x,'(?im)^\s*\{.{0,2}"?@context"?.*?\}\s*$','');$x=[regex]::Replace($x,'(?is)<!--\s*GK[^>]*-->','');$x=[regex]::Replace($x,'(?is)<nav\b[^>]*class=["''][^"'']*gk-design-toc[^"'']*["''][^>]*>.*?</nav>','');return $x.Trim()}
$root=Split-Path -Parent $PSScriptRoot;$stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$backup=Join-Path $root("backups\editorial-clean-$stamp");$reportDir=Join-Path $root 'reports';New-Item $reportDir -ItemType Directory -Force|Out-Null;if($Mode-eq'Apply'){New-Item $backup -ItemType Directory -Force|Out-Null};$rows=@()
foreach($x in($items|Sort-Object{[long]$_.id}-Unique)){$id=[long]$x.id;$title=[Net.WebUtility]::HtmlDecode([string]$x.title.rendered);$body=[Text.Encoding]::UTF8.GetBytes((@{id=$id}|ConvertTo-Json -Compress));$p=Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/read-post') -Method Post -Headers $uh -ContentType 'application/json; charset=utf-8' -Body $body;$old=[string]$p.content;$new=$old;$reason=@()
 if($old-match'gk-editorial-article|GKKB53_PREMIUM_DEPTH_END'){$core=Match-One $old '(?is)<section\b[^>]*class=["''][^"'']*gk-editorial-article[^"'']*["''][^>]*>(?<body>.*?)<!--\s*GKKB53_PREMIUM_DEPTH_END\s*-->';$authority=Match-One $old '(?is)<!--\s*GKKB53_DEEP_AUTHORITY_CONTENT_START\s*-->(?<body>.*?)<!--\s*GKKB53_DEEP_AUTHORITY_CONTENT_END\s*-->';$sources=Match-One $old '(?is)(?<body><h2>Offizielle Quellen</h2>\s*<ul>.*?</ul>)';$related=Match-One $old '(?is)(?<body><section\b[^>]*class=["''][^"'']*gk-related-box[^"'']*["''][^>]*>.*?</section>)';$faq=Match-One $old '(?is)(?<body><section\b[^>]*class=["''][^"'']*gk-faq-box[^"'']*["''][^>]*>.*?</section>)';$notice=Match-One $old '(?is)(?<body><section\b[^>]*class=["''][^"'']*gk-source-box[^"'']*["''][^>]*>.*?</section>)';$visual=Visual $title ([long]$x.featured_media);if(-not[string]::IsNullOrWhiteSpace($core)){$new='<article class="gk-clean-article" data-gk-clean="v1">'+$visual+(Clean-Core $core)+(Clean-Authority $authority)+$sources+$related+$faq+$notice+'</article>';$reason+='LAYERED_TEMPLATE'}}elseif([regex]::Matches($old,'(?is)<img\b').Count-eq0){$visual=Visual $title ([long]$x.featured_media);if($visual){$new=$visual+$old;$reason+='BODY_IMAGE'}}
 $new=Strip-Noise $new;if($new-ceq$old){continue};if($reason-contains'LAYERED_TEMPLATE'-and$new-match'gk_visual_object|gk-visual-placeholder|Dieser Abschnitt erweitert den Beitrag|\{.{0,2}"?@context'){throw "Bereinigung unvollstaendig: $id"};if($reason.Count-gt0-and$title-match'(?i)APL|TAE|Endleitung|DSL|Kupfer'-and[regex]::Matches($new,'(?is)<img\b').Count-eq0){throw "Fachbild fehlt: $id"};$status='READY';if($Mode-eq'Apply'){[IO.File]::WriteAllText((Join-Path $backup("post-$id.html")),$old,[Text.UTF8Encoding]::new($false));$payload=[Text.Encoding]::UTF8.GetBytes((@{id=$id;content=$new}|ConvertTo-Json -Compress));$u=Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/update-post') -Method Post -Headers $uh -ContentType 'application/json; charset=utf-8' -Body $payload;if($u.updated-ne$true){throw "Update nicht bestaetigt: $id"};$q=Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/read-post') -Method Post -Headers $uh -ContentType 'application/json; charset=utf-8' -Body $body;if([string]$q.content-cne$new){throw "Speicherpruefung fehlgeschlagen: $id"};$status='UPDATED_AND_VERIFIED'};$rows+=[pscustomobject]@{id=$id;title=$title;status=$status;reason=$reason-join',';images=[regex]::Matches($new,'(?is)<img\b').Count};Write-Host("$id $status")
}
if($Mode-eq'Apply'-and$rows.Count){$c=Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/clear-cache') -Method Post -Headers $uh -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes('{}'));if($c.cache_cleared-ne$true){throw 'Cache nicht geleert'}}
$rows | Export-Csv (Join-Path $reportDir("editorial-clean-$Mode-$stamp.csv")) -NoTypeInformation -Encoding UTF8
Write-Host("FERTIG: Modus=$Mode | Aktualisiert=$($rows.Count)")
